  +name : string
  +dateOfBirth : date
  +websiteUrl : string
}

class User {
  +id : string
  +name : string
  +address : string
}

class BusinessUser extends User {
  +vatNumber : string
}

class RegularUser extends User {
}

class Single {
}

class Hit {
}

class Album {
}

class AlbumTrack {
  +trackNumber : int
}

Artist "1" -- "*" Song : belongs to

BusinessUser "0..*" -- "*" Single : uploads
BusinessUser "0..*" -- "*" Hit : uploads

RegularUser "0..*" -- "*" Single : buys
RegularUser "0..*" -- "*" Album : buys

Album "1" *-- "1..*" AlbumTrack : consists of
AlbumTrack "1" -- "1" Hit : refers to

RegularUser "0..*" -- "0..*" Album : suggests

@enduml

